package com.superproductivity.superproductivity.widget

import android.content.Context
import android.content.SharedPreferences

/**
 * SharedPreferences-backed store for persisting share intent data across process death.
 * Uses commit() (synchronous) instead of apply() for crash safety during cold start.
 */
object ShareIntentQueue {
    private const val PREFS_NAME = "SuperProductivityShare"
    private const val KEY_PENDING_SHARE = "PENDING_SHARE_DATA"

    private fun getPrefs(context: Context): SharedPreferences {
        return context.applicationContext.getSharedPreferences(PREFS_NAME, Context.MODE_PRIVATE)
    }

    /**
     * Persist share data. Uses commit() for synchronous write — survives process death.
     * Synchronized: called from UI thread (handleIntent) and JS thread (getPendingShareData).
     */
    @Synchronized
    fun setPending(context: Context, json: String) {
        getPrefs(context).edit().putString(KEY_PENDING_SHARE, json).commit()
    }

    /**
     * Read and atomically clear persisted share data. Uses commit() for synchronous write.
     * Synchronized: called from UI thread (flushPendingShareIntent) and JS thread (getPendingShareData).
     * @return JSON string of share data, or null if empty
     */
    @Synchronized
    fun getAndClear(context: Context): String? {
        val prefs = getPrefs(context)
        val data = prefs.getString(KEY_PENDING_SHARE, null)
        if (data != null) {
            prefs.edit().remove(KEY_PENDING_SHARE).commit()
        }
        return data
    }
}


===== widget\CaptureInbox.kt =====
package com.superproductivity.superproductivity.widget

import android.content.Context
import org.json.JSONArray
import org.json.JSONObject
import java.io.File
import java.io.FileOutputStream
import java.io.IOException
import java.util.UUID

/**
 * Durable on-device inbox for tasks captured natively. Its only writer, the
 * startup quick-add overlay, was removed; the inbox stays so captures queued by
 * an older app version are still imported.
 *
 * One immutable JSON file per capture: [add] returns only after the file is
 * fsynced and renamed into place, reads never delete, and the app acknowledges
 * an entry only after the task it created is persisted. The capture id becomes
 * the task id, so a redelivered entry is recognised instead of duplicated.
 * Lives in noBackupFilesDir so a device restore cannot replay old captures.
 */
class CaptureInbox(private val dir: File) {

    /** @return the capture id; throws if the capture could not be stored. */
    fun add(
        title: String,
        source: String,
        createdAt: Long = System.currentTimeMillis(),
        id: String = UUID.randomUUID().toString(),
    ): String {
        val trimmed = title.trim()
        require(trimmed.isNotEmpty()) { "Blank capture title" }
        require(isValidId(id)) { "Invalid capture id" }
        synchronized(LOCK) {
            if (!dir.isDirectory && !dir.mkdirs()) {
                throw IOException("Could not create capture inbox")
            }
            val json = JSONObject()
                .put("v", VERSION)
                .put("id", id)
                .put("title", trimmed)
                .put("source", source)
                .put("createdAt", createdAt)
            val tmp = File(dir, "$id.tmp")
            FileOutputStream(tmp).use { out ->
                out.write(json.toString().toByteArray(Charsets.UTF_8))
                out.fd.sync()
            }
            if (!tmp.renameTo(File(dir, "$id.json"))) {
                tmp.delete()
                throw IOException("Could not commit capture")
            }
        }
        return id
    }

    /**
     * Non-destructive read of all valid captures, oldest first, as a JSON array.
     * An unreadable file is skipped (and kept) so it cannot block later captures.
     */
    fun pendingJson(): String {
        val entries = synchronized(LOCK) {
            val files = dir.listFiles { f -> f.isFile && f.name.endsWith(".json") }
                ?: return "[]"
            files.mapNotNull { parse(it) }
        }.sortedWith(compareBy({ it.optLong("createdAt") }, { it.optString("id") }))
        return JSONArray(entries).toString()
    }

    /** Deletes one capture. Returns true if it is gone (including already gone). */
    fun acknowledge(id: String): Boolean {
        if (!isValidId(id)) return false
        synchronized(LOCK) {
            val file = File(dir, "$id.json")
            return !file.exists() || file.delete()
        }
    }

    private fun parse(file: File): JSONObject? = try {
        val json = JSONObject(file.readText(Charsets.UTF_8))
        val id = json.optString("id")
        val isValid = json.optInt("v") == VERSION &&
            isValidId(id) &&
            file.name == "$id.json" &&
            json.optString("title").isNotBlank()
        if (isValid) json else null
    } catch (e: Exception) {
        null
    }

    companion object {
        const val VERSION = 1
        private const val DIR_NAME = "capture-inbox"
        private val LOCK = Any()
        private val ID_REGEX =
            Regex("^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$")

        fun forContext(context: Context): CaptureInbox =
            CaptureInbox(File(context.applicationContext.noBackupFilesDir, DIR_NAME))

        /** Ids cross the JS bridge and become file names; accept canonical UUIDs only. */
        fun isValidId(id: String): Boolean = ID_REGEX.matches(id)
    }
}

===== TrackingNotificationHelper.kt =====
package com.superproductivity.superproductivity.service

import android.app.Notification
import android.app.NotificationChannel
import android.app.NotificationManager
import android.app.PendingIntent
import android.content.Context
import android.content.Intent
import android.os.Build
import androidx.core.app.NotificationCompat
import com.superproductivity.superproductivity.CapacitorMainActivity
import com.superproductivity.superproductivity.R

object TrackingNotificationHelper {
    const val CHANNEL_ID = "sp_time_tracking_channel"
    const val NOTIFICATION_ID = 1001

    fun createChannel(context: Context) {
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
            val channel = NotificationChannel(
                CHANNEL_ID,
                "Time Tracking",
                NotificationManager.IMPORTANCE_LOW
            ).apply {
                description = "Shows active time tracking status"
                setShowBadge(false)
            }
            val notificationManager = context.getSystemService(NotificationManager::class.java)
            notificationManager.createNotificationChannel(channel)
        }
    }

    fun buildNotification(
        context: Context,
        taskTitle: String,
        elapsedMs: Long
    ): Notification {
        val contentIntent = Intent(context, CapacitorMainActivity::class.java).apply {
            flags = Intent.FLAG_ACTIVITY_SINGLE_TOP or Intent.FLAG_ACTIVITY_CLEAR_TOP
        }
        val contentPendingIntent = PendingIntent.getActivity(
            context,
            0,
            contentIntent,
            PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE
        )

        val pauseIntent = Intent(context, CapacitorMainActivity::class.java).apply {
            action = TrackingForegroundService.ACTION_PAUSE
            flags = Intent.FLAG_ACTIVITY_SINGLE_TOP or Intent.FLAG_ACTIVITY_CLEAR_TOP
        }
        val pausePendingIntent = PendingIntent.getActivity(
            context,
            1,
            pauseIntent,
            PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE
        )

        val doneIntent = Intent(context, CapacitorMainActivity::class.java).apply {
            action = TrackingForegroundService.ACTION_DONE
            flags = Intent.FLAG_ACTIVITY_SINGLE_TOP or Intent.FLAG_ACTIVITY_CLEAR_TOP
        }
        val donePendingIntent = PendingIntent.getActivity(
            context,
            2,
            doneIntent,
            PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE
        )

        // SystemUI renders the ticking elapsed time via the chronometer, so the
        // service never has to re-post the notification just to advance the
        // timer — a 1 Hz notify() loop kept the process busy around the clock
        // and showed up as battery drain (#8243).
        return NotificationCompat.Builder(context, CHANNEL_ID)
            .setSmallIcon(R.drawable.ic_stat_sp)
            .setContentTitle(taskTitle)
            .setContentIntent(contentPendingIntent)
            .setWhen(System.currentTimeMillis() - elapsedMs)
            .setShowWhen(true)
            .setUsesChronometer(true)
            .setOngoing(true)
            .setOnlyAlertOnce(true)
            .setSilent(true)
            .addAction(0, "Pause", pausePendingIntent)
            .addAction(0, "Done", donePendingIntent)
            .setCategory(NotificationCompat.CATEGORY_PROGRESS)
            .setPriority(NotificationCompat.PRIORITY_LOW)
            .build()
    }
}


===== FocusModeNotificationHelper.kt =====
package com.superproductivity.superproductivity.service

import android.app.Notification
import android.app.NotificationChannel
import android.app.NotificationManager
import android.app.PendingIntent
import android.content.Context
import android.content.Intent
import android.media.AudioAttributes
import android.media.RingtoneManager
import android.os.Build
import android.util.Log
import androidx.core.app.NotificationCompat
import androidx.core.app.NotificationManagerCompat
import com.superproductivity.superproductivity.CapacitorMainActivity
import com.superproductivity.superproductivity.R

object FocusModeNotificationHelper {
    private const val TAG = "FocusModeNotifHelper"
    const val CHANNEL_ID = "sp_focus_mode_channel"
    const val COMPLETION_CHANNEL_ID = "sp_focus_complete_channel"
    const val NOTIFICATION_ID = 1002
    const val COMPLETION_NOTIFICATION_ID = 1003

    fun createChannel(context: Context) {
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
            val channel = NotificationChannel(
                CHANNEL_ID,
                "Focus Mode",
                NotificationManager.IMPORTANCE_LOW
            ).apply {
                description = "Shows focus mode timer status"
                setShowBadge(false)
            }
            val notificationManager = context.getSystemService(NotificationManager::class.java)
            notificationManager.createNotificationChannel(channel)
        }
    }

    fun buildNotification(
        context: Context,
        title: String,
        taskTitle: String?,
        remainingMs: Long,
        isCountdown: Boolean,
        isPaused: Boolean,
        isBreak: Boolean
    ): Notification {
        val contentIntent = Intent(context, CapacitorMainActivity::class.java).apply {
            flags = Intent.FLAG_ACTIVITY_SINGLE_TOP or Intent.FLAG_ACTIVITY_CLEAR_TOP
        }
        val contentPendingIntent = PendingIntent.getActivity(
            context,
            10,
            contentIntent,
            PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE
        )

        val builder = NotificationCompat.Builder(context, CHANNEL_ID)
            .setSmallIcon(R.drawable.ic_stat_sp)
            .setContentTitle(buildTitle(title, taskTitle))
            .setContentIntent(contentPendingIntent)
            .setOngoing(true)
            .setOnlyAlertOnce(true)
            .setSilent(true)
            .setCategory(NotificationCompat.CATEGORY_PROGRESS)
            .setPriority(NotificationCompat.PRIORITY_LOW)

        // SystemUI's chronometer renders the ticking timer so the service never
        // re-posts the notification each second — the old 1 Hz notify() loop was
        // a steady battery drain (#8243). Paused sessions show static text.
        if (isPaused) {
            builder.setContentText(formatDuration(remainingMs))
        } else if (isCountdown) {
            builder
                .setWhen(System.currentTimeMillis() + remainingMs)
                .setShowWhen(true)
                .setUsesChronometer(true)
                .setChronometerCountDown(true)
        } else {
            // Flowtime: remainingMs holds the elapsed time, counting up
            builder
                .setWhen(System.currentTimeMillis() - remainingMs)
                .setShowWhen(true)
                .setUsesChronometer(true)
        }

        // Add Pause/Resume action
        if (isPaused) {
            val resumeIntent = Intent(context, CapacitorMainActivity::class.java).apply {
                action = FocusModeForegroundService.ACTION_RESUME
                flags = Intent.FLAG_ACTIVITY_SINGLE_TOP or Intent.FLAG_ACTIVITY_CLEAR_TOP
            }
            val resumePendingIntent = PendingIntent.getActivity(
                context,
                11,
                resumeIntent,
                PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE
            )
            builder.addAction(0, "Resume", resumePendingIntent)
        } else {
            val pauseIntent = Intent(context, CapacitorMainActivity::class.java).apply {
                action = FocusModeForegroundService.ACTION_PAUSE
                flags = Intent.FLAG_ACTIVITY_SINGLE_TOP or Intent.FLAG_ACTIVITY_CLEAR_TOP
            }
            val pausePendingIntent = PendingIntent.getActivity(
                context,
                12,
                pauseIntent,
                PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE
            )
            builder.addAction(0, "Pause", pausePendingIntent)
        }

        // Add Skip (for breaks) or Complete (for work sessions) action
        if (isBreak) {
            val skipIntent = Intent(context, CapacitorMainActivity::class.java).apply {
                action = FocusModeForegroundService.ACTION_SKIP
                flags = Intent.FLAG_ACTIVITY_SINGLE_TOP or Intent.FLAG_ACTIVITY_CLEAR_TOP
            }
            val skipPendingIntent = PendingIntent.getActivity(
                context,
                13,
                skipIntent,
                PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE
            )
            builder.addAction(0, "Skip", skipPendingIntent)
        } else {
            val completeIntent = Intent(context, CapacitorMainActivity::class.java).apply {
                action = FocusModeForegroundService.ACTION_COMPLETE
                flags = Intent.FLAG_ACTIVITY_SINGLE_TOP or Intent.FLAG_ACTIVITY_CLEAR_TOP
            }
            val completePendingIntent = PendingIntent.getActivity(
                context,
                14,
                completeIntent,
                PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE
            )
            builder.addAction(0, "Complete", completePendingIntent)
        }

        return builder.build()
    }

    private fun buildTitle(focusTitle: String, taskTitle: String?): String {
        return if (taskTitle.isNullOrBlank()) {
            focusTitle
        } else {
            "$focusTitle: $taskTitle"
        }
    }

    fun formatDuration(ms: Long): String {
        val totalSeconds = ms / 1000
        val minutes = totalSeconds / 60
        val seconds = totalSeconds % 60
        return String.format("%d:%02d", minutes, seconds)
    }

    fun createCompletionChannel(context: Context) {
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
            val alarmSound = RingtoneManager.getDefaultUri(RingtoneManager.TYPE_ALARM)
                ?: RingtoneManager.getDefaultUri(RingtoneManager.TYPE_NOTIFICATION)

            val audioAttributes = AudioAttributes.Builder()
                .setUsage(AudioAttributes.USAGE_ALARM)
                .setContentType(AudioAttributes.CONTENT_TYPE_SONIFICATION)
                .build()

            val channel = NotificationChannel(
                COMPLETION_CHANNEL_ID,
                "Focus Mode Completion",
                NotificationManager.IMPORTANCE_HIGH
            ).apply {
                description = "Alerts when focus session or break completes"
                setShowBadge(true)
                enableVibration(true)
                vibrationPattern = longArrayOf(0, 500, 200, 500)
                setSound(alarmSound, audioAttributes)
            }
            val notificationManager = context.getSystemService(NotificationManager::class.java)
            notificationManager.createNotificationChannel(channel)
        }
    }

    fun showCompletionNotification(
        context: Context,
        title: String,
        message: String,
        isBreak: Boolean
    ) {
        Log.d(TAG, "Showing completion notification: isBreak=$isBreak")
        createCompletionChannel(context)

        val contentIntent = Intent(context, CapacitorMainActivity::class.java).apply {
            flags = Intent.FLAG_ACTIVITY_SINGLE_TOP or Intent.FLAG_ACTIVITY_CLEAR_TOP
        }
        val contentPendingIntent = PendingIntent.getActivity(
            context,
            20,
            contentIntent,
            PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE
        )

        val builder = NotificationCompat.Builder(context, COMPLETION_CHANNEL_ID)
            .setSmallIcon(R.drawable.ic_stat_sp)
            .setContentTitle(title)
            .setContentText(message)
            .setContentIntent(contentPendingIntent)
            .setAutoCancel(true)
            .setPriority(NotificationCompat.PRIORITY_HIGH)
            .setCategory(NotificationCompat.CATEGORY_ALARM)

        if (isBreak) {
            val skipIntent = Intent(context, CapacitorMainActivity::class.java).apply {
                action = FocusModeForegroundService.ACTION_SKIP
                flags = Intent.FLAG_ACTIVITY_SINGLE_TOP or Intent.FLAG_ACTIVITY_CLEAR_TOP
            }
            val skipPendingIntent = PendingIntent.getActivity(
                context,
                21,
                skipIntent,
                PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE
            )
            builder.addAction(0, "Skip Break", skipPendingIntent)
        } else {
            val completeIntent = Intent(context, CapacitorMainActivity::class.java).apply {
                action = FocusModeForegroundService.ACTION_COMPLETE
                flags = Intent.FLAG_ACTIVITY_SINGLE_TOP or Intent.FLAG_ACTIVITY_CLEAR_TOP
            }
            val completePendingIntent = PendingIntent.getActivity(
                context,
                22,
                completeIntent,
                PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE
            )
            builder.addAction(0, "Complete", completePendingIntent)
        }

        try {
            NotificationManagerCompat.from(context).notify(COMPLETION_NOTIFICATION_ID, builder.build())
        } catch (e: SecurityException) {
            Log.e(TAG, "No permission to show completion notification", e)
        }
    }

